import{s}from"/dist/chunk-6k8ey1xy.js";function i(){return s("div",{class:"markdown-body",dangerouslySetInnerHTML:{__html:`<h1>Marknote 介绍</h1>&lt;img src="images/marknote-screenshot.jpg" style="border: 2px solid #ccc; max-width: 100%"&gt;
<ul><li><a href="https://yuekcc.github.io/marknote/">在线预览</a></li><li><a href="https://github.com/yuekcc/marknote">源码</a></li></ul><p>[TOC]</p><h2>想法</h2><p>Marknote 最初的想法是山寨一个 <a href="https://github.com/vvpvvp/book-cli">boot-cli</a>。book-cli 是一个纯前端渲染的网站工具。类似概念的著名产品还有：<a href="https://github.com/docsifyjs/docsify">docsify</a>。当然 docsify 功能更多。相对本地执行的静态网站生成器，例如 <a href="https://gohugo.io/">hugo</a>，纯前端型的工具功能更加简单（简陋），而且几乎不存在 SEO 可能。不过好处就是，用户可以更专注于内容本身，也可以在线使用。比如通过 github 直接编写文章并发布新网站。</p><h2>特性</h2><ul><li>页面布局改为顶部导航，下面为正文内容的布局<ul><li>正文部分保持左右布局，方便组织文章；左侧是导航，右则是文章</li><li>文章可以指定使用不同的侧栏</li><li>增加打印机优化的样式</li></ul></li><li>markdown 增加了一个简单的 <code>[TOC]</code> 语法拓展</li><li>主题支持大屏小屏设备</li><li>打印机优化</li></ul><p>网站主页，实际上是仓库的 README.md 文件。选择这个文档为主页的目的是与 github 这样的托管服务保持一致。在 github.io 不能访问时，可以直接访问仓库，起码内容还可以正常浏览。</p><blockquote><p>github.io 域名在我用的网络偶然会抽风，访问不了</p></blockquote><p>网站除主页外，应该有一个侧栏，侧栏可以起到链接、跳转的功能。这样就可以将多个文章组织为一个整体。参考一些使用 <a href="https://vuepress.vuejs.org/zh/">vuepress</a> 的文章网站，我也给文章的连接增加了 <code>sidebar</code> 参数，用于指定渲染文章时使用不同的侧栏。在概念上，就可以实现文章分类。</p><p>顶部导航因为内容比较简单，就直接使用 html 编写。</p><h2>后续功能计划</h2><ul><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled /><del>front matter 支持</del></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled checked />完善打印样式</li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled /><del>完善用户交互效果</del></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled /><del>缓存</del></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled checked />pwa 支持（仅支持安装为应用）</li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled checked />文档</li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled checked />实现一个更好 <code>[TOC]</code> 拓展</li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled checked />增加一套主题<ul><li><del>[ ] 支持 light/dark 切换</del></li></ul></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled checked />语法高亮</li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled checked />使用 sycamore 重写（新仓库：<a href="https://github.com/yuekcc/docutil">https://github.com/yuekcc/docutil</a>）<ul><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" disabled checked />改名 marknote =&gt; docutil</li></ul></li></ul><h2>用户</h2><ul><li>https://yuekcc.github.io/</li><li>https://turn-left.github.io/</li><li>https://yuekcc.github.io/marknote/</li><li>https://lambdadriver.space/</li></ul><hr /><ul><li>2021.11.6：初稿</li><li>2021.11.7: 完成部分计划</li></ul>`}},void 0,!1,void 0,this)}export{i as default};
